import{c as o,Q as r,j as n,m as a}from"./chunks/framework.ByJJFMw8.js";const p=JSON.parse('{"title":"RAG 搭建企业私有与个人知识库（知识点笔记）","description":"","frontmatter":{},"headers":[],"relativePath":"posts/llm/RAG搭建企业私有与个人知识库知识点笔记.md","filePath":"posts/llm/RAG搭建企业私有与个人知识库知识点笔记.md","lastUpdated":null}'),d={name:"posts/llm/RAG搭建企业私有与个人知识库知识点笔记.md"};function e(s,t,i,l,g,u){return r(),n("div",null,[...t[0]||(t[0]=[a(`<h1 id="rag-搭建企业私有与个人知识库-知识点笔记" tabindex="-1">RAG 搭建企业私有与个人知识库（知识点笔记） <a class="header-anchor" href="#rag-搭建企业私有与个人知识库-知识点笔记" aria-label="Permalink to &quot;RAG 搭建企业私有与个人知识库（知识点笔记）&quot;">​</a></h1><blockquote><p>来源：<a href="https://didilili.github.io/ai-agents-from-zero/#/2-RAG%E6%90%AD%E5%BB%BA%E4%BC%81%E4%B8%9A%E7%A7%81%E6%9C%89%26%E4%B8%AA%E4%BA%BA%E7%9F%A5%E8%AF%86%E5%BA%93" target="_blank" rel="noreferrer">ai-agents-from-zero 第 2 章《RAG 搭建企业私有&amp;个人知识库》</a>（<a href="https://github.com/didilili/ai-agents-from-zero" target="_blank" rel="noreferrer">GitHub 仓库</a>），原文配图与完整操作步骤见原站。整理于 2026-11-26。</p></blockquote><p>这是全书第一篇把 RAG 落到产品和平台上的章节。第 1 章讲&quot;为什么选 RAG&quot;，本章讲&quot;决定用 RAG 后怎么把知识库搭起来&quot;，代码侧实现留在第 18/19 章。本文提炼其中最值得记住的知识点：RAG 的两阶段流程、效果排查框架、平台选型与关键调参。</p><h2 id="一、rag-是什么-开卷答题-不是再学一遍" tabindex="-1">一、RAG 是什么：开卷答题，不是再学一遍 <a class="header-anchor" href="#一、rag-是什么-开卷答题-不是再学一遍" aria-label="Permalink to &quot;一、RAG 是什么：开卷答题，不是再学一遍&quot;">​</a></h2><ul><li><strong>定义</strong>：RAG（Retrieval-Augmented Generation，检索增强生成）= 把<strong>信息检索</strong>与<strong>大模型生成</strong>结合的应用架构。核心思路四步：用户提问 → 先去外部知识源找资料 → 把&quot;问题 + 资料&quot;一起发给大模型 → 基于资料生成答案。 <blockquote><p><strong>RAG = 先查资料，再回答问题。</strong></p></blockquote></li><li>三个单词的工程含义：<strong>Retrieval</strong>（找到最相关的资料片段）→ <strong>Augmented</strong>（把资料拼进当前 Prompt/上下文）→ <strong>Generation</strong>（模型基于资料作答）。</li><li>形象比喻：RAG 是<strong>让模型开卷答题</strong>，而不是&quot;再学一遍新知识&quot;——不改模型参数、不改变模型的&quot;大脑&quot;，只是外挂一个可检索的资料层，在运行时补充模型当前需要的上下文。</li></ul><h2 id="二、为什么需要-rag-三类天然限制" tabindex="-1">二、为什么需要 RAG：三类天然限制 <a class="header-anchor" href="#二、为什么需要-rag-三类天然限制" aria-label="Permalink to &quot;二、为什么需要 RAG：三类天然限制&quot;">​</a></h2><p>RAG 不是&quot;更高级的聊天技巧&quot;，而是针对大模型单独使用时的三类限制：</p><table tabindex="0"><thead><tr><th>限制</th><th>说明</th></tr></thead><tbody><tr><td><strong>知识冻结</strong></td><td>训练完成后知识不会自动更新；模型越大训练成本越高、越不可能天天重训，&quot;最新/刚变更/实时&quot;信息天然是短板</td></tr><tr><td><strong>私有知识缺失</strong></td><td>企业制度、内部文档、项目资料、课程讲义不在公开训练语料里，直接问要么不知道要么半猜半答</td></tr><tr><td><strong>幻觉与不可追溯</strong></td><td>没把握时容易&quot;猜一个像样答案&quot;，且说不清依据来自哪里</td></tr></tbody></table><blockquote><p>关键认知：很多业务问题本质上不是&quot;模型不会&quot;，而是&quot;模型没看到资料&quot;。RAG 的价值是让系统在回答前先去你的资料里找证据，回答从&quot;靠印象发挥&quot;变成&quot;有依据地作答&quot;。</p></blockquote><h2 id="三、两阶段流程-离线建库-在线检索生成" tabindex="-1">三、两阶段流程：离线建库 + 在线检索生成 <a class="header-anchor" href="#三、两阶段流程-离线建库-在线检索生成" aria-label="Permalink to &quot;三、两阶段流程：离线建库 + 在线检索生成&quot;">​</a></h2><p>理解 RAG 最重要的是拆成<strong>两个阶段</strong>，而不是一句&quot;先检索再生成&quot;：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阶段一 知识库构建（离线，面向原始资料）：</span></span>
<span class="line"><span>  本地文档(PDF/Word/MD/网页) → 文档解析与清洗 → 文本切分 Chunk</span></span>
<span class="line"><span>  → Embedding 文本转向量 → 向量库(存文本块+向量+元数据)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>阶段二 检索与生成（在线，面向用户提问）：</span></span>
<span class="line"><span>  用户问题 → 问题向量化 → 向量相似度检索相关文本块</span></span>
<span class="line"><span>  → Prompt 增强(问题+检索结果) → LLM 生成 → 带依据的回答</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>R-G-A 与步骤的对应：<strong>检索</strong> = 问题嵌入 → 查询向量 → 相似度搜索；<strong>增强</strong> = 把检索结果注入提示模板；<strong>生成</strong> = LLM 输出答案。</p><p>后面换任何平台/框架，界面不同但底层不变，对应关系（LangChain 对象）：文档 → <code>Document</code>、切分 → <code>TextSplitter</code>、向量化 → <code>Embeddings</code>、检索 → <code>Retriever</code>、增强输入 → <code>PromptTemplate</code>。</p><h2 id="四、四个最容易混的词与-同一套-embedding-铁律" tabindex="-1">四、四个最容易混的词与&quot;同一套 Embedding&quot;铁律 <a class="header-anchor" href="#四、四个最容易混的词与-同一套-embedding-铁律" aria-label="Permalink to &quot;四、四个最容易混的词与&quot;同一套 Embedding&quot;铁律&quot;">​</a></h2><table tabindex="0"><thead><tr><th>词</th><th>是什么</th><th>易混点</th></tr></thead><tbody><tr><td><strong>知识库</strong></td><td>承载外部知识的<strong>整体容器</strong>（文档、分块、向量、元数据、检索配置）</td><td>≠ 向量库</td></tr><tr><td><strong>向量库</strong></td><td>知识库内部做相似度检索的<strong>存储组件</strong></td><td>只是知识库的一部分</td></tr><tr><td><strong>Embedding</strong></td><td>把文本变成向量的模型/过程</td><td>定义&quot;语义坐标系&quot;</td></tr><tr><td><strong>Prompt 增强</strong></td><td>把检索结果交给模型的那一步</td><td>对应 RAG 的&quot;A&quot;</td></tr></tbody></table><blockquote><p><strong>为什么建库和提问必须用同一套嵌入模型</strong>：嵌入模型本质上定义了一套&quot;语义坐标系&quot;。建库用模型 A、提问用模型 B，就像拿两种不同的尺子量距离，相似度会乱掉，检索效果明显变差。</p></blockquote><h2 id="五、rag-效果乘法公式与排查决策树" tabindex="-1">五、RAG 效果乘法公式与排查决策树 <a class="header-anchor" href="#五、rag-效果乘法公式与排查决策树" aria-label="Permalink to &quot;五、RAG 效果乘法公式与排查决策树&quot;">​</a></h2><blockquote><p><strong>RAG 效果 = 文档质量 × 解析质量 × 切分质量 × 检索质量 × 重排质量 × Prompt 组织质量 × 生成模型质量 × 评测闭环</strong></p></blockquote><p>乘号含义：<strong>只要某个环节特别差，整体就被明显拉低</strong>。所以知识库答不准时不要一上来就怪模型，先看现象再往回查：</p><table tabindex="0"><thead><tr><th>现象</th><th>优先排查</th></tr></thead><tbody><tr><td>完全找不到资料</td><td>入库链路：文档是否上传、解析是否成功、Embedding 是否一致</td></tr><tr><td>召回内容答非所问</td><td>检索策略：关键词/向量检索、Top K、阈值、Rerank</td></tr><tr><td>资料找到了但模型乱答</td><td>Prompt 约束：仅基于资料回答、允许说&quot;不知道&quot;、要求引用来源</td></tr><tr><td>答案不完整或漏重点</td><td>上下文组织：Chunk 大小、Overlap、Top K、上下文窗口</td></tr><tr><td>无法追溯来源</td><td>元数据与引用：文件名、页码、标题、段落 ID</td></tr></tbody></table><p>RAG 最难的环节通常不在&quot;上传文件&quot;，而在：文档是否被正确解析、切块是否太大或太碎、Embedding 是否合适、检索是否真的相关、拼进上下文的噪音多不多。</p><h2 id="六、知识库是什么与三类平台选型" tabindex="-1">六、知识库是什么与三类平台选型 <a class="header-anchor" href="#六、知识库是什么与三类平台选型" aria-label="Permalink to &quot;六、知识库是什么与三类平台选型&quot;">​</a></h2><ul><li><strong>知识库 = 让模型能访问你自己的资料，并在提问时按需调用</strong>。从用户视角是&quot;能问答的资料仓库&quot;，从工程视角是文档、切块、Embedding、检索、元数据、召回策略的集合。</li><li>三层价值：<strong>管理资料</strong>（不再散落网盘/聊天记录）、<strong>快速检索</strong>（不用手动翻 PDF）、<strong>增强生成</strong>（检索结果还能继续总结/改写/问答）。</li><li>适合人群：小微企业主、职场人/自由职业者、师生（复习型知识库）、普通人（旅行/阅读/求职资料）——知识库不是企业专属。</li></ul><p>平台按能力定位分三类（功能和价格随版本变化，以官方为准）：</p><table tabindex="0"><thead><tr><th>类型</th><th>代表工具</th><th>特点</th><th>适合</th></tr></thead><tbody><tr><td><strong>个人轻量型</strong></td><td>Cherry Studio / AnythingLLM / ima</td><td>桌面/图形化、上手快，可接云模型与本地模型</td><td>个人或小团队快速验证 Demo</td></tr><tr><td><strong>平台协作型</strong></td><td>Dify / FastGPT</td><td>LLM 应用与工作流编排平台，知识库可接对话应用、工作流、Agent</td><td>从 Demo 走向团队协作和应用交付</td></tr><tr><td><strong>复杂文档解析型</strong></td><td>RAGFlow</td><td>强调复杂文档解析、高精度混合检索、重排、可视化干预</td><td>长 PDF、扫描件、复杂表格等对解析质量要求高的场景</td></tr></tbody></table><h2 id="七、cherry-studio-个人向桌面化模型工作台" tabindex="-1">七、Cherry Studio：个人向桌面化模型工作台 <a class="header-anchor" href="#七、cherry-studio-个人向桌面化模型工作台" aria-label="Permalink to &quot;七、Cherry Studio：个人向桌面化模型工作台&quot;">​</a></h2><ul><li><strong>定位</strong>：个人向、桌面化、模型聚合型 AI 工作台。特点：小白友好、<strong>一问多答</strong>（同一问题多模型对比）、助手市场（千余个行业助手）、服务商模型聚合（OpenAI/Gemini/Anthropic/Azure 规范接入）、支持全本地场景（数据安全敏感者友好）。</li><li><strong>实操要点</strong>：接入模型时要分清两个角色——<strong>聊天模型（LLM）负责最终回答</strong>，<strong>Embedding 模型负责把文档和问题变成向量用于检索</strong>；先配聊天模型，建知识库前必须再添加嵌入模型。</li><li><strong>两种使用方式</strong>：①<strong>直接检索</strong>——只搜知识库不生成，能看到相关片段和匹配得分，很适合排查效果；②<strong>基于知识库生成</strong>——才是完整 RAG（检索→增强→生成）。</li><li>流程五步：接聊天模型 → 接 Embedding 模型 → 上传文档建库 → 先检索相关内容 → 再基于知识库生成。</li></ul><blockquote><p>踩坑点：上传文件若含大量手写内容、复杂表格、扫描件、公式或复杂版式，解析效果明显下降。很多人以为&quot;RAG 效果差&quot;是模型问题，实际上常常是文档解析阶段已经出了问题。可先用 Doc2X 等专门解析工具做预处理再入库。</p></blockquote><h2 id="八、ima-更轻量的-c-端知识助手" tabindex="-1">八、ima：更轻量的 C 端知识助手 <a class="header-anchor" href="#八、ima-更轻量的-c-端知识助手" aria-label="Permalink to &quot;八、ima：更轻量的 C 端知识助手&quot;">​</a></h2><ul><li><strong>定位</strong>：比 Cherry Studio 更偏 C 端、更轻量、上手成本更低，价值在于快速建立&quot;知识库问答&quot;的使用直觉；可定制化不如 Dify。</li><li>特点：零上手成本、多端同步（客户端/小程序/网页）、共享知识库（可分享协作）、接入平台方提供的大模型。</li><li><strong>网页内容也能入库</strong>：把微信公众号相关主题文章加入 ima 即可构成知识库再问答。 <blockquote><p><strong>知识库不等于&quot;上传 PDF&quot;</strong>。只要资料能整理成可用文本，就有机会成为知识库的一部分。</p></blockquote></li><li>第三方知识库：可查看/加入他人共享的知识库，对应&quot;知识库协作与复用&quot;能力——团队场景下知识库是多人共享的知识入口。</li></ul><h2 id="九、dify-分段设置-切块是-rag-最关键的调参点" tabindex="-1">九、Dify 分段设置：切块是 RAG 最关键的调参点 <a class="header-anchor" href="#九、dify-分段设置-切块是-rag-最关键的调参点" aria-label="Permalink to &quot;九、Dify 分段设置：切块是 RAG 最关键的调参点&quot;">​</a></h2><ul><li><strong>Dify 定位</strong>：开源 LLM 应用开发平台，&quot;应用平台 + 工作流平台 + 知识库平台&quot;综合形态。知识库可继续接入聊天应用、工作流、Agent、API 服务。</li><li><strong>对象关系三级</strong>：知识库（整体容器）→ 文档（导入的数据源）→ 分段 Chunk（切分后的可检索片段）。</li><li>支持源数据格式：长文本（TXT/Markdown/DOCX/HTML/JSON/PDF）+ 结构化数据（CSV/Excel）。</li></ul><p>为什么先分段：LLM 上下文窗口有限，需先切分再召回关联度最高的几段。<strong>切太粗带来噪音，切太细把语义切碎</strong>。</p><table tabindex="0"><thead><tr><th>配置项</th><th>作用</th><th>影响与经验值</th></tr></thead><tbody><tr><td><strong>分段标识符</strong></td><td>按什么边界切块：<code>\\n</code> 按换行、<code>\\n\\n</code> 按空行（段落）</td><td>选得不合适会把整段话切碎，检索容易只命中半句；可用&quot;预览块&quot;检查划分</td></tr><tr><td><strong>分段最大长度</strong></td><td>单块字数/字符上限</td><td>太大→噪音进 Prompt；太小→语义拆散漏信息。可从 200～800 字（约 100～500 token）起步</td></tr><tr><td><strong>分段重叠长度</strong></td><td>相邻块重复一段文字，避免边界语义断裂</td><td>一般取分段最大长度的 <strong>10%～20%</strong>；太大造成重复、存储浪费与检索噪声</td></tr><tr><td><strong>索引方式</strong></td><td>高质量（Embedding 向量索引，更准但耗 token）vs 经济；Q&amp;A 模式</td><td>文档本身就是问答对形式时 Q&amp;A 更契合</td></tr></tbody></table><p>预处理时还可过滤 URL、邮箱等无关内容。入门案例：用《刑法》TXT（法条天然分段清晰、知识边界明确）建库，便于观察检索是否准确。</p><h2 id="十、dify-检索设置-rerank-top-k-阈值-混合检索" tabindex="-1">十、Dify 检索设置：Rerank / Top K / 阈值 / 混合检索 <a class="header-anchor" href="#十、dify-检索设置-rerank-top-k-阈值-混合检索" aria-label="Permalink to &quot;十、Dify 检索设置：Rerank / Top K / 阈值 / 混合检索&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置项</th><th>作用</th><th>影响与经验值</th></tr></thead><tbody><tr><td><strong>Embedding 模型</strong></td><td>把文档块和用户问题都转向量算语义相似度</td><td>建库和检索必须<strong>同一个</strong>模型，否则不在同一向量空间</td></tr><tr><td><strong>Rerank 模型</strong></td><td>对向量检索的候选块，用专门模型对&quot;问题+候选&quot;打更精细的相关性分</td><td>能显著提升送给模型的上下文质量，但增加延迟与成本；要求高的场景值得开启</td></tr><tr><td><strong>Top K</strong></td><td>最多取几条文档块交给后续步骤</td><td>K 太小漏关键信息，K 太大塞噪音耗 token；一般先试 <strong>5</strong> 再微调</td></tr><tr><td><strong>Score 阈值</strong></td><td>相似度下限，达不到就丢弃</td><td>阈值高更干净但可能漏召回；低则噪音多。&quot;找不到内容&quot;→降阈值，&quot;召回太杂&quot;→升阈值</td></tr><tr><td><strong>混合检索</strong></td><td>向量检索 + 全文检索，合并去重排序</td><td>文档里既有自然语言段落又有条目编号、专有名词、法条编号时，比纯向量检索更稳</td></tr></tbody></table><p>测试用提示词（法律小助手案例，体现了 Prompt 约束）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你是一个法律小助手，请只根据知识库中的信息，简要回答用户提问的案件触犯了哪些法律</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="十一、三类平台各自适合验证什么" tabindex="-1">十一、三类平台各自适合验证什么 <a class="header-anchor" href="#十一、三类平台各自适合验证什么" aria-label="Permalink to &quot;十一、三类平台各自适合验证什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>一句话定位</th><th>适合验证</th></tr></thead><tbody><tr><td>Cherry Studio</td><td>个人快速搭知识库试试效果</td><td>个人知识助手、多模型对比</td></tr><tr><td>ima</td><td>普通用户低门槛体验知识库问答</td><td>使用直觉、网页资料入库</td></tr><tr><td>Dify</td><td>把知识库放进应用、工作流和团队协作</td><td>应用化交付、检索参数调优</td></tr><tr><td>RAGFlow</td><td>复杂文档解析 + 高精度检索</td><td>把解析/召回质量当核心竞争力</td></tr></tbody></table><blockquote><p><strong>本章最有价值的工程结论：RAG 的效果不是&quot;上传完文件&quot;那一刻决定的，而是由文档质量、切块策略、Embedding 质量、检索策略和重排策略共同决定的。</strong></p></blockquote><h2 id="十二、最值得记的三问三答" tabindex="-1">十二、最值得记的三问三答 <a class="header-anchor" href="#十二、最值得记的三问三答" aria-label="Permalink to &quot;十二、最值得记的三问三答&quot;">​</a></h2><ol><li><strong>知识库效果不好先查什么？</strong> 先看问题表现：完全找不到资料→查入库链路（文档入库、切块、Embedding 一致性）；召回杂→调 Top K、阈值、Rerank；召回对但答乱→查提示词与引用约束。</li><li><strong>为什么&quot;上传了文件&quot;≠&quot;知识库可用&quot;？</strong> 文件还要被解析、清洗、切块、向量化、写入索引，且查询时能被正确召回——任何一环出问题，用户看到的都是&quot;答不准&quot;。质量由整条链路决定，不是上传动作决定。</li><li><strong>Top K / 阈值 / Rerank 怎么跟新人解释？</strong> 用&quot;查资料&quot;类比：Top K 决定拿几段材料，阈值决定太不相关的材料要不要丢，Rerank 决定候选材料重新排序。答案漏信息可能是 K 太小或阈值太高，答案跑偏可能是 K 太大或缺重排。</li></ol>`,45)])])}const b=o(d,[["render",e]]);export{p as __pageData,b as default};
